/bin/bash -lc "/work1/zixuan/envs/conda_envs/causalmemagent/bin/python -c 'import glob,json,collections
scores=list(map(json.loads,open(\"pilot/peval/pair_scores.jsonl\")));by=collections.defaultdict(list)
for s in scores:by[(s[\"family_idx\"],s[\"target_sibling\"])].append(s)
def top1(v):return sorted(v,key=lambda c:(-c[\"sim_embed\"],-c[\"sim_tf\"],c[\"memory_id\"]))[0]
vr={r[\"memory_id\"]:r for r in map(json.loads,open(\"pilot/peval/phi_d/comparator_v0/verdicts.jsonl\"))}
def trig_pred(r):return any(x[\"code\"]==\"PRED_OP_MISMATCH\" and x[\"level\"]==\"contradict\" for x in r[\"reasons\"])
for model in [\"qwen7b\",\"qwen3b\"]:
 suc={}
 for p in glob.glob(\"/work1/zixuan/outputs/agent_memory/pilot/rollouts_\"+model+\"_shard*-of-*.jsonl\"):
  for r in map(json.loads,open(p)):
   m=r[\"meta\"];suc[(m[\"family_idx\"],m[\"sibling_idx\"],m[\"cell\"],m[\"seed\"])]=int(r[\"success\"])
 out={k:[] for k in [\"N\",\"always\",\"oracleP\",\"true_top1\",\"true_all4\",\"cmp_nonconf\",\"predop_nonconf\"]}; acc={k:collections.Counter() for k in [\"oracleP\",\"cmp_nonconf\",\"predop_nonconf\"]}; den=collections.Counter()
 for (f,si),cs in by.items():
  c=top1(cs);cell=c[\"cell\"];rv=vr[c[\"memory_id\"]];den[cell]+=4
  for sd in range(4):
   n=suc[(f,si,\"N\",sd)];a=suc[(f,si,cell,sd)];all4=[suc[(f,si,z,sd)] for z in [\"A00\",\"A01\",\"A10\",\"A11\"]]
   out[\"N\"].append(n);out[\"always\"].append(a);out[\"oracleP\"].append(a if c[\"P\"]==1 else n);out[\"true_top1\"].append(max(n,a));out[\"true_all4\"].append(max([n]+all4))
   for name,ad in [(\"cmp_nonconf\",rv[\"verdict\"]"'!="contradict"),("predop_nonconf",not trig_pred(rv))]:out[name].append(a if ad else n);acc[name][cell]+=int(ad)
   acc["oracleP"][cell]+=int(c["P"]==1)
 base=sum(out["N"])/640
 print(model,"base",base,"top1dist",dict(den))
 for k,v in out.items():print(k,"succ",sum(v)/640,"uplift_pp",100*(sum(v)/640-base),"accept",(sum(acc[k].values())/640 if k in acc else None),"acc_by",dict(acc[k]) if k in acc else None)'"'"

